    "pub_date": "2026-08-28 00:15:03",
    "author": "“国家移民管理局”微信公号",
    "description": "2026年第5号 2026年8月26日10时30分许，因尼泊尔一侧发生大规模泥石流灾害，造成西藏自治区日喀则市吉隆口岸重大人员伤亡、失联。目前，吉隆口岸道路、通信中断，仍有可能发生次生灾害，抢险救灾工作正在紧张有序开展。为防止对前往边境管理区人员生命财产造成危害，影响抢险救灾工作开展，维护边境地区通行秩序，国家移民管理局决定，自2026年8月28日零时起，暂停签发前往西藏自治区日喀则市电子边境管理区通行证。持有已经签发的前往地包含日喀则…",
    "content": "2026年第5号 2026年8月26日10时30分许，因尼泊尔一侧发生大规模泥石流灾害，造成西藏自治区日喀则市吉隆口岸重大人员伤亡、失联。目前，吉隆口岸道路、通信中断，仍有可能发生次生灾害，抢险救灾工作正在紧张有序开展。为防止对前往边境管理区人员生命财产造成危害，影响抢险救灾工作开展，维护边境地区通行秩序，国家移民管理局决定，自2026年8月28日零时起，暂停签发前往西藏自治区日喀则市电子边境管理区通行证。持有已经签发的前往地包含日喀则市的电子边境管理区通行证人员，暂勿前往上述地区。恢复时间另行发布。 特此公告。 …"
