    "content": "新华社伦敦8月27日电（记者吴黎明 高文成）记者近日从英国大英图书馆馆藏检索系统查悉，《新时代治国理政纪实》第一卷已正式入藏大英图书馆。 《新时代治国理政纪实》第一卷由新华通讯社编撰，收录新华社长篇通讯26篇、新闻图片41幅，图文并茂呈现习近平总书记领航中国砥砺奋进的伟大实践，充分彰显习近平新时代中国特色社会主义思想强大的真理力量与实践伟力。 大英图书馆是英国国家图书馆，也是世界上规模最大、最具影响力的学术图书馆之一，珍藏有图书、手稿、报刊、地图、音像资料等各类文献，发挥着重要的学术研究和文化保存作用。 据了解，《…"
