    "author": "Brian7",
    "description": "一 转眼间到了人生的第 32 个年头。但是此时的我，却一点也不想迎来自己的 33 岁，而是多希望时光能够倒流，回到六天前的那个中午…… 8 月 21 日中午，我奶奶在家中不慎跌倒，后脑直接撞在墙上，随即休克陷入昏迷，后脑的血怎么也止不住。 那时的我，还在几千公里外的出租屋里，焦头烂额地刷着求职网站。 得知消息后，我立刻订了最近一班机票赶回去。但因为老家是东北的六线小镇，几经转折真正赶到医院时，已经是第三天的晚上。爸爸、叔叔和姑姑都一言不…",
    "content": "一 转眼间到了人生的第 32 个年头。但是此时的我，却一点也不想迎来自己的 33 岁，而是多希望时光能够倒流，回到六天前的那个中午…… 8 月 21 日中午，我奶奶在家中不慎跌倒，后脑直接撞在墙上，随即休克陷入昏迷，后脑的血怎么也止不住。 那时的我，还在几千公里外的出租屋里，焦头烂额地刷着求职网站。 得知消息后，我立刻订了最近一班机票赶回去。但因为老家是东北的六线小镇，几经转折真正赶到医院时，已经是第三天的晚上。爸爸、叔叔和姑姑都一言不发地坐在 ICU 病房外的长椅上。 我低声问了问妈妈，她默默地把病历递给了我。 …"
