    "content": "8月27日晚，国家防总副总指挥、水利部部长李国英再次主持专题会商，滚动分析研判普热普强藏布堰塞湖发展态势及可能影响，进一步安排部署堰塞湖险情处置和西藏吉隆泥石流灾害抢险救援水利支持工作。 李国英强调，要坚决贯彻落实习近平总书记重要指示精神，按照李强总理批示要求，始终把人民生命安全放在首位，进一步强化细化落实各项应急处置措施，严防发生次生灾害，全力以赴做好抢险救援水利支持工作。一要加强雨水情监测预报。水文应急监测队伍要准确掌握东林藏布、普热普强藏布等流域雨水情和堰塞湖水位、蓄水量及上游来水、下泄水量等动态变化，为险情…"
