    "content": "新华社香港8月27日电（黄茜恬）龙马社版话剧《我爱桃花》27日在香港西九文化区自由空间上演，带领观众进入一场唐朝与现代交融的戏中戏。 此次活动由香港北京社团总会主办。邹静之编剧作品《我爱桃花》自2003年剧本面世以来,以各种形式被搬上舞台，成为当代小剧场经典。龙马社版《我爱桃花》由张国立导演并主演，“87版”电视剧《红楼梦》演员联合出演话剧。 《我爱桃花》源自明代话本《型世言》，以中国传统文化中象征爱情的桃花作为意象，将古代和现代两条线索交织并行，探究了自古以来人们的情感困惑。 全国政协常委、香港北京社团总会会长施…"
