    "content": "首次选择了国内一个小的中转站，倍率很低，大约 0.2X 的样子，用了两周，感觉反应很慢，以为是中转站原因，换了 AIHubMix ，充值$5,不到一个 1 个小时就没 Token 了。。。真心震惊我了。。。 现在在用 plus 会员，感觉比中转响应要快 但是我的使用强度并不高，该如何选择？用 CC+API 可以根据使用强度收费，但是用了 AIHubMix 感觉 Token 消耗也太快了，是我使用的问题吗？"
