    "author": "吴瑶,罗晨",
    "description": "新华社德黑兰8月27日电 据伊朗伊斯兰共和国通讯社27日报道，伊朗外交部长阿拉格齐当天在首都德黑兰与到访的卡塔尔首相兼外交大臣穆罕默德举行会谈，双方就缓和地区紧张局势、为对话创造条件等问题交换意见。 另据卡塔尔外交部当天发表的声明，双方在会谈中讨论了目前围绕分阶段框架进行的磋商，包括在霍尔木兹海峡设立一条临时航运通道。双方还就联合清除该海峡水雷事宜达成一致。 声明还说，阿拉格齐感谢卡塔尔为缓解紧张局势、推动对话与谈判所作的努力。穆罕默德…",
    "content": "新华社德黑兰8月27日电 据伊朗伊斯兰共和国通讯社27日报道，伊朗外交部长阿拉格齐当天在首都德黑兰与到访的卡塔尔首相兼外交大臣穆罕默德举行会谈，双方就缓和地区紧张局势、为对话创造条件等问题交换意见。 另据卡塔尔外交部当天发表的声明，双方在会谈中讨论了目前围绕分阶段框架进行的磋商，包括在霍尔木兹海峡设立一条临时航运通道。双方还就联合清除该海峡水雷事宜达成一致。 声明还说，阿拉格齐感谢卡塔尔为缓解紧张局势、推动对话与谈判所作的努力。穆罕默德强调应尊重邻国主权以及航行自由，同时应继续努力缓解地区紧张局势，通过对话解决分歧…"
