    "description": "新华社马德里8月27日电（记者孟鼎博）据西班牙比列纳市政府消息，当地时间27日清晨，位于西班牙东南部阿利坎特省的比列纳博物馆遭到盗窃，馆藏“比列纳宝藏”大部分黄金文物被盗。 比列纳市政府对媒体表示，当天清晨5时16分左右，博物馆警报被触发。警方随后封锁现场，搜集指纹等证据并调取监控录像。当地媒体说，窃贼破窗进入博物馆，作案过程仅持续数分钟。比列纳市长塞尔丹说，被盗文物价值约150万欧元。 据介绍，“比列纳宝藏”1963年在当地出土，共有…",
    "content": "新华社马德里8月27日电（记者孟鼎博）据西班牙比列纳市政府消息，当地时间27日清晨，位于西班牙东南部阿利坎特省的比列纳博物馆遭到盗窃，馆藏“比列纳宝藏”大部分黄金文物被盗。 比列纳市政府对媒体表示，当天清晨5时16分左右，博物馆警报被触发。警方随后封锁现场，搜集指纹等证据并调取监控录像。当地媒体说，窃贼破窗进入博物馆，作案过程仅持续数分钟。比列纳市长塞尔丹说，被盗文物价值约150万欧元。 据介绍，“比列纳宝藏”1963年在当地出土，共有数十件黄金、白银、铁等材质的器物。其中包括金碗、金手镯等，黄金总重近10公斤，是…"
