    "description": "苹果这次备货挺足的，就是发货时间比较长。 选 M5 MAX 128G 的用户占比应该会比较多，算是性价比高的一款。 Mac Studio 刀法精准，M5 MAX 最高给到 128g ，M5 Ultra 给你 96g ，不给 128g 让你感觉很鸡肋，直接跳到 256g ，跨度大。就赌你在不想选低一个档的芯片跟内存带宽情况下，咬牙上 256g 要漫长等待了，10 月 24 日才发货。",
    "content": "苹果这次备货挺足的，就是发货时间比较长。 选 M5 MAX 128G 的用户占比应该会比较多，算是性价比高的一款。 Mac Studio 刀法精准，M5 MAX 最高给到 128g ，M5 Ultra 给你 96g ，不给 128g 让你感觉很鸡肋，直接跳到 256g ，跨度大。就赌你在不想选低一个档的芯片跟内存带宽情况下，咬牙上 256g 要漫长等待了，10 月 24 日才发货。"
