    "author": "白佳丽,袁宇宽",
    "description": "初秋时节，天津市宝坻区大口屯镇西刘举人庄村，连片蜜薯田铺展在蓝天下，叶片随风翻涌。泥土下，一垄垄蜜薯正静待丰收。 2026年8月17日，天津市宝坻区大口屯镇西刘举人庄村党支部委员马建国在蜜薯田间查看作物长势。新华社记者 袁宇宽 摄 “现在的日子，可比以前美多了。”67岁的村民马福永掰着手指细数变化：家里的五六亩地流转给村集体，每人每年有1200元流转收益；农忙时，还能到产业基地就近务工，在家门口再挣一份收入；保险由村里统一购买，逢年过节…",
    "content": "初秋时节，天津市宝坻区大口屯镇西刘举人庄村，连片蜜薯田铺展在蓝天下，叶片随风翻涌。泥土下，一垄垄蜜薯正静待丰收。 2026年8月17日，天津市宝坻区大口屯镇西刘举人庄村党支部委员马建国在蜜薯田间查看作物长势。新华社记者 袁宇宽 摄 “现在的日子，可比以前美多了。”67岁的村民马福永掰着手指细数变化：家里的五六亩地流转给村集体，每人每年有1200元流转收益；农忙时，还能到产业基地就近务工，在家门口再挣一份收入；保险由村里统一购买，逢年过节还有米、月饼等福利。 “村‘两委’班子办事公道，发展有思路，大伙儿心气顺，都愿意…"
