    "author": "魏弘毅",
    "description": "新华社北京8月27日电（记者魏弘毅）记者从水利部了解到，水利部27日对西藏启动洪水防御Ⅳ级应急响应。 受8月26日尼泊尔一侧发生泥石流灾害影响，尼泊尔错坚河汇入我国境内普热普强藏布的交汇处附近形成堰塞湖，截至8月27日上午估算蓄水量约200万立方米。据预报，受降雨影响，堰塞湖未来3天入湖水量约300万立方米，溃泄风险高，可能造成吉隆口岸等下游沿线地区再次受灾。 为应对风险，水利部指导督促西藏自治区水利厅密切关注堰塞体稳定性、蓄水体量和雨…",
    "content": "新华社北京8月27日电（记者魏弘毅）记者从水利部了解到，水利部27日对西藏启动洪水防御Ⅳ级应急响应。 受8月26日尼泊尔一侧发生泥石流灾害影响，尼泊尔错坚河汇入我国境内普热普强藏布的交汇处附近形成堰塞湖，截至8月27日上午估算蓄水量约200万立方米。据预报，受降雨影响，堰塞湖未来3天入湖水量约300万立方米，溃泄风险高，可能造成吉隆口岸等下游沿线地区再次受灾。 为应对风险，水利部指导督促西藏自治区水利厅密切关注堰塞体稳定性、蓄水体量和雨水情变化，强化应急值守、监测预报和会商研判，科学分析堰塞湖溃泄洪水影响，精准掌握…"
