    "description": "8月27日晚，新华社记者探访吉隆镇应急集结地，看到救援物资已经规整好，为后续救援做周全准备。 8月26日10时30分许，因尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。 记者：黄智琪、普布次仁、薛晨、洛卓嘉措 新华社音视频部制作",
