    "author": "",
    "description": "",
    "content": "快科技8月27日消息，中芯国际公布2026年半年报，上半年拿到一份相当亮眼的经营数据。 报告期实现营收386.35亿元，同比上涨19.4%；归母净利润44.67亿元，同比大涨94.2% ；扣非净利润29.94亿元，同比增长57.2%。 现金流表现格外突出，经营活动现金净流入207.60亿元，同比暴涨252%，毛利率来到23.2%，相比去年同期提升1.3个百分点。 简单来说，卖芯片晶圆不仅赚得多，手里落到的真金白银也变多了。 业绩大涨主要来自三个方面，晶圆出货量上涨、产品平均售价提高，还有产品结构的变化。 现在AI配…"
