    "content": "新华社北京8月27日电 墨西哥一名网络主播8月初在街头直播时遭枪杀。墨西哥安全部长奥马尔·加西亚·阿富奇26日说，警方已逮捕一名嫌疑人，并在继续追捕其他涉案人员。 根据阿富奇发表的声明，落网嫌疑人名为赫苏斯·阿尔韦托·N，调查人员在墨西哥中部普埃布拉州发现其行踪。警方26日发起抓捕行动，遭3人武装拒捕，最终击毙1人、逮捕阿尔韦托等2人，缴获枪支弹药和车辆。 被枪杀的网络主播塞萨尔·加斯特卢姆在社交媒体平台拥有数十万粉丝，主要发布搞笑视频。本月4日，他在墨西哥北部锡那罗亚州首府库利亚坎市一家快餐店外与两名朋友一起直播…"
