    "content": "新华社拉萨8月27日电 记者27日从西藏吉隆泥石流灾害救援指挥部了解到，吉隆县泥石流灾害发生后，各救援力量赶赴现场，全面开展群众与游客转移安置工作。截至目前，受泥石流灾害影响的499名群众完成安置，滞留的555名游客完成转移。 灾情发生后，日喀则市对受灾害威胁区域群众做到应转尽转、不落一人，同步统筹做好集中安置点各项生活服务保障。目前，受影响的499名人员已全部得到妥善安置，其中包括萨勒乡郭巴村180人、色琼村40人、拉比村107人，吉隆镇老江村55人、冲色村88人，以及施工队29人。 同时，相关部门组织力量，对计…"
