    "description": "高额彩礼，是一些农村家庭的挂心事。 日前，在江西赣州召开的部分省份农村高额彩礼问题综合整治经验交流会上，一组数据引人关注：经过持续整治，农村高额彩礼水平呈现持续下降趋势，婚嫁铺张浪费得到有效纠治。农村移风易俗村级跟踪观察点监测数据显示，彩礼金额在5万元以下的“低彩礼”家庭占比由2022年的16%上升至2025年的27.6%。 5月20日，新人们在安徽合肥市暨中铁四局百对新人集体婚礼仪式上。新华社发（刘玉才 摄） 把农村“天价彩礼”降下来…",
