    "content": "新华社南昌8月27日电（记者陈浚武）在江西东北部的群山之间，有这样一座千年古村：汛期洪水围村，却始终进不了村；大雨倾盆而下，村内积水不进屋。这就是位于江西省景德镇市浮梁县勒功乡的千年古村——沧溪村。 江西省景德镇市浮梁县勒功乡沧溪村。（无人机照片）新华社记者 陈浚武 摄 沧溪村距今已有1700余年历史。村内现存明清古建筑近140座、古桥3座、古街巷6条、古祠堂旧址4处，古牌坊3座。2010年获评“中国历史文化名村”，2012年首批列入中国传统村落名录。 沧溪村。新华社记者 陈浚武 摄 千年来，沧溪屡遭洪水围村却不进…"
