    "content": "中新网南宁8月27日电(黄艳梅 郑清欣 卢明发)据广西南宁水文中心预测，郁江南宁市区段将于8月27日20时前后出现75.4米左右的洪峰水位(警戒水位73.0米)。据气象部门预报，受台风“紫檀”和“沙德尔”先后影响，未来几天南宁仍可能有明显降雨过程。"
