    "description": "新华社坎帕拉8月27日电（记者聂祖国）世界卫生组织非洲区域办事处27日发布新闻公报说，乌干达本轮由本迪布焦型埃博拉病毒引发的疫情正式结束，世卫组织和非洲疾病预防控制中心对此表示欢迎。 新闻公报说，乌干达最后一名埃博拉患者于7月16日结束治疗并出院，此后该国连续42天未报告新的确诊病例。42天相当于埃博拉病毒最长潜伏期的两倍，这一监测期的完成是一个关键节点。 根据世卫组织标准，自最后一名确诊患者不再具有病毒传播能力之日起，连续42天无新增…",
    "content": "新华社坎帕拉8月27日电（记者聂祖国）世界卫生组织非洲区域办事处27日发布新闻公报说，乌干达本轮由本迪布焦型埃博拉病毒引发的疫情正式结束，世卫组织和非洲疾病预防控制中心对此表示欢迎。 新闻公报说，乌干达最后一名埃博拉患者于7月16日结束治疗并出院，此后该国连续42天未报告新的确诊病例。42天相当于埃博拉病毒最长潜伏期的两倍，这一监测期的完成是一个关键节点。 根据世卫组织标准，自最后一名确诊患者不再具有病毒传播能力之日起，连续42天无新增确诊病例，一国方可宣布疫情结束。 世卫组织表示，在国际合作伙伴的支持下，乌干达通…"
