    "content": "新华社北京8月27日电（记者张千千）财政部、中国人民银行、金融监管总局日前对外发布通知，明确进一步做好财政金融协同促内需政策有关工作。目前，工商银行、农业银行、中国银行、建设银行、交通银行、邮储银行等多家银行已发布公告，明确中小微企业贷款贴息及服务业经营主体贷款贴息政策的落实情况。 可享受贴息的贷款规模上限有所提高。相关银行公告称，单户在单家经办机构可享受中小微企业贷款贴息的贷款规模上限由每年5000万元提高至7500万元；单户在单家经办机构可享受服务业经营主体贷款贴息的贷款规模上限由每年1000万元提高至2000…"
