    "content": "新华社北京8月27日电（记者万倩仪、吴梦桐）外交部发言人林剑27日表示，泥石流灾害造成中尼两国重大人员伤亡、失联。中方正同尼泊尔方面密切沟通、协调配合，共同做好搜救工作。 当日例行记者会上，有记者问：8月26日，因尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。中方是否同尼方进行沟通？是否掌握在尼受灾中国公民和中国境内受灾外国公民情况？ 林剑说，此次泥石流灾害造成中尼两国重大人员伤亡、失联。中方向尼泊尔政府和受灾民众表示诚挚慰问。中方正同尼方密切沟通、协调配合，共同做好搜救工作，将根据尼…"
