    "content": "新华社香港8月27日电（记者舒娜）香港生产力促进局27日举行“全民AI”普惠计划启动礼，旨在推动人工智能技术在香港的普及与应用，助力中小企业升级转型。 今年香港特区政府推出“全民AI培训”计划，通过数码港、科技园和生产力促进局等多方合作，目标在今明两年举办超过200项活动，预计惠及约5万人次。此前，数码港从“基础普及”角度，重点面向学生、家长、长者以及弱势社群，普及和提升他们对AI的认知。香港科技园则聚焦“专业转化”，主要对象是大学生、青年研究员及专业人士，通过进阶课堂、应用比赛、实习与职业博览等活动，将AI知识转…"
