    "content": "新华社西藏吉隆8月27日电（刘言明、张磊峰）8月26日，尼泊尔一侧突发大规模泥石流灾害，西藏日喀则市吉隆县吉隆口岸遭受波及，造成重大人员伤亡、失联，当地通信、交通通行条件严重受损，抢险救援任务刻不容缓。 灾情发生后，西部战区依案启动应急响应机制，发挥联合作战指挥优势，组织地面、空中力量先期勘察灾情，结合灾区兵力、医疗、交通等实际情况科学部署救援任务，并派出战区指导组进驻一线。 8月27日10时30分许，西部战区指导组搭乘运-20抵达西藏某高原机场，随即赶赴吉隆灾区一线，全面统筹调度军队各类救援力量，统一规划部署抢险…"
