    "content": "截至8月27日，2026年暑期档票房超119亿元，创下近三年最好成绩。《八仙！》票房超17亿元，《去你的岛》《三国第一部：争洛阳》等各具特色……在新片云集的暑期档，动画电影格外亮眼。 人们约上三五好友，在影院邂逅奇幻“八仙”，品读热血“三国”，尽享大银幕带来的视听魅力。 这是动画电影的夏天，是中国动画市场的火热时刻。 国漫兴 全民赏 “拯救苍生，一点儿也不蠢”“不问得失，只认对错”……《八仙！》火了！八个凡人假扮神仙、守护苍生的故事，点燃了暑期动画观影热潮。 “小朋友心里能埋下一颗种子，青年人能从中看到选择和坚持，…"
