    "title": "中基协：7月证券期货经营机构共备案私募资管产品3583只，同比增加91.2%",
    "link": "https://36kr.com/newsflashes/3957725854793094?f=rss",
    "pub_date": "2026-08-27 20:32:51",
    "author": "",
    "description": "36氪获悉，中基协数据显示，2026年7月，证券期货经营机构共备案私募资管产品3,583只，环比增加16.94%，同比增加91.20%；设立规模1,228.19亿元，环比增加13.94%，同比增加15.90%。截至2026年7月底，证券期货经营机构私募资管产品规模合计13.20万亿元，较上月底增加734.43亿元，环比增长0.56%。",
