    "content": "新华社北京8月27日电（记者顾天成）8月26日10时30分许，因尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。国家航天局迅速启动航天应急响应机制，统筹协调卫星资源对泥石流受灾区域进行应急成像，同步查询灾区历史影像。 据悉，自26日19时完成首批数据影像紧急推送以来，截至27日17时，国家航天局已分批将5景灾前影像、10景灾后影像推送至应急管理部国家减灾中心、水利部信息中心、自然资源部国家基础地理信息中心，以及高分西藏、四川、甘肃等省级数据与应用中心，为灾情研判和减灾救灾提供及时有效的卫…"
